def comps_for(val):
    seen=set(); cs=[]
    for r in range(len(grid)):
      for c in range(len(grid[0])):
        if grid[r][c]!=val or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          p=q.pop(); comp.append(p)
          for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            t=(p[0]+dr,p[1]+dc)
            if 0<=t[0]<len(grid) and 0<=t[1]<len(grid[0]) and grid[t[0]][t[1]]==val and t not in seen:
              seen.add(t); q.append(t)
        cs.append(comp)
    return cs
