def bbox(comp): return (min(r for r,c in comp),max(r for r,c in comp),min(c for r,c in comp),max(c for r,c in comp))
b4=[bbox(c) for c in cs4]
def candidates(comp):
    out=[]
    for dr,dc,name in D:
      for steps in range(1,50):
        moved={(r+dr*steps,c+dc*steps) for r,c in comp}
        hits=[(p,q) for i,obj in enumerate(cs4) for p in moved for q in obj if p==q]
        if hits:
          # first contact must be through interior face (perpendicular coordinate strictly inside object bounds)
          good=True
          for i,(p,q) in [(i,(p,q)) for i,obj in enumerate(cs4) for p in moved for q in obj if p==q]:
            r,c=q; r0,r1,c0,c1=b4[i]
            if dr and not (c0<c<c1): good=False
            if dc and not (r0<r<r1): good=False
          if good: out.append((steps-1,name,[(p,q) for p,q in hits]))
          break
    return sorted(out)
